"use client";

import { useState } from "react";
import type { Job } from "@/lib/mock-data";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  ClipboardIcon,
  CheckIcon,
  PencilSquareIcon,
} from "@heroicons/react/20/solid";

interface JobEditFormProps {
  job: Job;
  onCancel: () => void;
  onOpenScript?: (scriptType: string) => void;
}

/* ── Shared form primitives ──────────────────────────────────────────────── */

function SectionHeader({ children }: { children: React.ReactNode }) {
  return (
    <h3 className="text-xs font-semibold uppercase tracking-wider text-text-secondary/60 mb-3 mt-2 pt-4 border-t border-border/40 first:border-0 first:pt-0 first:mt-0">
      {children}
    </h3>
  );
}

function FormField({
  label,
  children,
  hint,
}: {
  label: string;
  children: React.ReactNode;
  hint?: string;
}) {
  return (
    <div className="space-y-1.5">
      <label className="block text-xs font-medium text-text-secondary">
        {label}
      </label>
      {children}
      {hint && (
        <p className="text-[10px] text-text-secondary/40">{hint}</p>
      )}
    </div>
  );
}

function TextInput({
  defaultValue,
  placeholder,
}: {
  defaultValue?: string;
  placeholder?: string;
}) {
  return (
    <input
      type="text"
      readOnly
      defaultValue={defaultValue}
      placeholder={placeholder}
      className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2.5 text-sm font-mono text-text-primary placeholder:text-text-secondary/40 outline-none focus:border-primary/40 focus:ring-1 focus:ring-primary/20 transition-colors"
    />
  );
}

function TextArea({
  defaultValue,
  placeholder,
  rows = 3,
}: {
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
}) {
  return (
    <textarea
      readOnly
      defaultValue={defaultValue}
      placeholder={placeholder}
      rows={rows}
      className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2.5 text-sm font-mono text-text-primary placeholder:text-text-secondary/40 outline-none focus:border-primary/40 focus:ring-1 focus:ring-primary/20 transition-colors resize-none"
    />
  );
}

function SelectInput({
  defaultValue,
  options,
}: {
  defaultValue: string;
  options: { value: string; label: string }[];
}) {
  return (
    <select
      defaultValue={defaultValue}
      className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2.5 text-sm font-mono text-text-primary outline-none focus:border-primary/40 focus:ring-1 focus:ring-primary/20 transition-colors cursor-pointer appearance-none"
    >
      {options.map((opt) => (
        <option key={opt.value} value={opt.value}>
          {opt.label}
        </option>
      ))}
    </select>
  );
}

function ToggleSwitch({ defaultChecked }: { defaultChecked: boolean }) {
  return (
    <button
      type="button"
      className={`relative inline-flex h-5 w-9 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ${
        defaultChecked ? "bg-primary" : "bg-border"
      }`}
    >
      <span
        className={`pointer-events-none inline-block h-4 w-4 transform rounded-full bg-text-primary shadow transition duration-200 ${
          defaultChecked ? "translate-x-4" : "translate-x-0"
        }`}
      />
    </button>
  );
}

function TabSelector({
  value,
  options,
}: {
  value: string;
  options: { value: string; label: string }[];
}) {
  return (
    <div className="inline-flex rounded-lg border border-border overflow-hidden">
      {options.map((opt) => (
        <button
          key={opt.value}
          type="button"
          className={cn(
            "px-3 py-1.5 text-xs font-medium transition-colors cursor-pointer",
            value === opt.value
              ? "bg-primary text-bg"
              : "bg-surface-elevated/40 text-text-secondary hover:text-text-primary"
          )}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

/* ── Script Preview Card ─────────────────────────────────────────────────── */

function ScriptPreviewCard({
  title,
  content,
  onClick,
  isMain,
}: {
  title: string;
  content: string;
  onClick: () => void;
  isMain?: boolean;
}) {
  const [copied, setCopied] = useState(false);
  const lines = content ? content.split("\n") : [];
  const previewLines = lines.slice(0, 4);
  const hasMore = lines.length > 4;
  const isEmpty = !content;

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!content) return;
    navigator.clipboard.writeText(content).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  };

  return (
    <div
      onClick={onClick}
      className="rounded-lg border border-border bg-surface overflow-hidden transition-all duration-200 hover:border-primary/30 hover:shadow-[0_0_12px_-4px_oklch(0.70_0.15_55_/_0.08)] cursor-pointer group flex flex-col"
    >
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-border/50">
        <div className="flex items-center gap-1.5">
          {isMain && (
            <PencilSquareIcon className="h-3 w-3 text-primary/50" />
          )}
          <span className="text-[11px] font-medium text-text-secondary group-hover:text-text-primary transition-colors">
            {title}
          </span>
        </div>
        <button
          onClick={handleCopy}
          className="flex items-center justify-center h-6 w-6 rounded text-text-secondary/30 hover:text-text-secondary hover:bg-surface-elevated transition-colors cursor-pointer"
          aria-label="Copy to clipboard"
        >
          {copied ? (
            <CheckIcon className="h-3.5 w-3.5 text-success" />
          ) : (
            <ClipboardIcon className="h-3.5 w-3.5" />
          )}
        </button>
      </div>

      {/* Code preview */}
      <div
        className="flex-1 px-3 py-2 font-mono text-[11px] leading-relaxed min-h-[72px]"
        style={{ background: "oklch(0.12 0.01 250)" }}
      >
        {isEmpty ? (
          <span className="text-text-secondary/25 italic">
            No script configured
          </span>
        ) : (
          <>
            {previewLines.map((line, i) => (
              <div key={i} className="text-text-primary/60 truncate">
                {line}
              </div>
            ))}
            {hasMore && (
              <div className="text-text-secondary/30 mt-0.5">
                ... {lines.length - 4} more line{lines.length - 4 !== 1 ? "s" : ""}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

/* ── Main Form ───────────────────────────────────────────────────────────── */

export function JobEditForm({ job, onCancel, onOpenScript }: JobEditFormProps) {
  const envVarStr =
    Object.keys(job.envVars).length > 0
      ? Object.entries(job.envVars)
          .map(([k, v]) => `${k}=${v}`)
          .join("\n")
      : "";

  return (
    <div className="flex-1 overflow-y-auto p-6">
      <div className="max-w-3xl space-y-4">
        {/* ── 1. General ───────────────────────────────────────────── */}
        <SectionHeader>General</SectionHeader>
        <FormField label="Job Name">
          <TextInput defaultValue={job.name} />
        </FormField>
        <div className="grid grid-cols-2 gap-4">
          <FormField label="Enabled">
            <div className="pt-1">
              <ToggleSwitch defaultChecked={job.enabled} />
            </div>
          </FormField>
          <FormField label="Execution Type">
            <TabSelector
              value={job.execType}
              options={[
                { value: "ShellCommand", label: "Shell Command" },
                { value: "ScriptFile", label: "Script File" },
              ]}
            />
          </FormField>
        </div>

        {/* ── 2. Schedule ──────────────────────────────────────────── */}
        <SectionHeader>Schedule</SectionHeader>
        <div className="grid grid-cols-2 gap-4">
          <FormField label="Cron Expression">
            <TextInput defaultValue={job.schedule} placeholder="*/5 * * * *" />
          </FormField>
          <FormField label="Schedule Mode">
            <SelectInput
              defaultValue={job.scheduleMode}
              options={[
                { value: "cron", label: "Cron" },
                { value: "interval", label: "Wait for Completion" },
              ]}
            />
          </FormField>
        </div>
        <FormField label="Timezone">
          <TextInput defaultValue="UTC" />
        </FormField>

        {/* ── 3. Execution ─────────────────────────────────────────── */}
        <SectionHeader>Execution</SectionHeader>
        <div className="grid grid-cols-3 gap-3">
          <ScriptPreviewCard
            title="Pre-Run Script"
            content={job.preHook}
            onClick={() => onOpenScript?.("script:pre-run")}
          />
          <ScriptPreviewCard
            title="Main Script"
            content={job.command}
            onClick={() => onOpenScript?.("script:main")}
            isMain
          />
          <ScriptPreviewCard
            title="Post-Run Script"
            content={job.postHook}
            onClick={() => onOpenScript?.("script:post-run")}
          />
        </div>

        {/* ── 4. Runtime ───────────────────────────────────────────── */}
        <SectionHeader>Runtime</SectionHeader>
        <FormField label="Working Directory">
          <TextInput defaultValue={job.workingDir} />
        </FormField>
        <div className="grid grid-cols-3 gap-4">
          <FormField label="Timeout">
            <TextInput defaultValue={job.timeout} />
          </FormField>
          <FormField label="Max Retries">
            <TextInput defaultValue={String(job.maxRetries)} />
          </FormField>
          <FormField label="Allow Concurrent">
            <div className="pt-1">
              <ToggleSwitch defaultChecked={job.allowConcurrent} />
            </div>
          </FormField>
        </div>

        {/* ── 5. Environment ───────────────────────────────────────── */}
        <SectionHeader>Environment</SectionHeader>
        <FormField
          label="Environment Variables"
          hint="One KEY=VALUE per line. These are passed to the job process."
        >
          <TextArea
            defaultValue={envVarStr}
            placeholder="KEY=VALUE (one per line)"
            rows={4}
          />
        </FormField>
        <FormField label="Log Environment">
          <div className="flex items-center gap-2 pt-1">
            <ToggleSwitch defaultChecked={job.logEnvironment} />
            <span className="text-[11px] text-text-secondary/50">
              Log full environment variables when the job runs
            </span>
          </div>
        </FormField>

        {/* ── 6. Actions ───────────────────────────────────────────── */}
        <div className="flex items-center gap-3 pt-5 border-t border-border">
          <Button variant="primary">Save Changes</Button>
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
        </div>
      </div>
    </div>
  );
}
