"use client";

import { useState, useEffect } from "react";
import { Badge } from "@/components/ui/badge";
import { type Run } from "@/lib/mock-data";
import { fetchRunLog } from "@/lib/api";
import { cn } from "@/lib/utils";
import { ChevronRightIcon } from "@heroicons/react/20/solid";

const statusVariant: Record<Run["status"], "success" | "error" | "info" | "warning"> = {
  success: "success",
  failed: "error",
  running: "info",
  killed: "warning",
};

const statusLabel: Record<Run["status"], string> = {
  success: "Completed",
  failed: "Failed",
  running: "Running",
  killed: "Killed",
};

interface RunLogViewerProps {
  run: Run;
  onBackToOverview: () => void;
}

export function RunLogViewer({ run, onBackToOverview }: RunLogViewerProps) {
  const [logs, setLogs] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    fetchRunLog(run.id).then((lines) => {
      setLogs(lines);
      setLoading(false);
    });
  }, [run.id]);

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* Breadcrumb header */}
      <div className="flex items-center gap-1.5 px-6 pt-5 pb-3 text-sm">
        <button
          onClick={onBackToOverview}
          className="text-text-secondary hover:text-text-primary transition-colors cursor-pointer font-medium"
        >
          {run.jobName}
        </button>
        <ChevronRightIcon className="h-4 w-4 text-text-secondary/40" />
        <span className="text-text-primary font-medium">Run Log</span>
      </div>

      {/* Run ID and Job ID labels */}
      <div className="flex flex-col gap-1 px-6 pb-3">
        <div className="flex items-center gap-2 text-xs">
          <span className="text-text-secondary/50 font-medium">Run ID:</span>
          <span className="font-mono text-text-primary">{run.id}</span>
        </div>
        <div className="flex items-center gap-2 text-xs">
          <span className="text-text-secondary/50 font-medium">Job ID:</span>
          <span className="font-mono text-text-secondary">{run.jobId}</span>
        </div>
      </div>

      {/* Run metadata strip */}
      <div className="flex items-center gap-4 px-6 pb-4 flex-wrap">
        <Badge variant={statusVariant[run.status]}>
          {statusLabel[run.status]}
        </Badge>
        <div className="flex items-center gap-3 text-xs text-text-secondary font-mono">
          <span>Started: {run.started}</span>
          <span className="text-border">|</span>
          <span>Duration: {run.duration}</span>
          <span className="text-border">|</span>
          <span>
            Exit:{" "}
            <span
              className={cn(
                run.exitCode === 0
                  ? "text-success"
                  : run.exitCode === null
                    ? "text-info"
                    : "text-error"
              )}
            >
              {run.exitCode === null ? "--" : run.exitCode}
            </span>
          </span>
          <span className="text-border">|</span>
          <span>Cost: {run.cost}</span>
        </div>
      </div>

      {/* Log viewer */}
      <div
        className="flex-1 mx-6 mb-6 rounded-lg border border-border overflow-auto font-mono text-xs leading-relaxed"
        style={{ background: "oklch(0.12 0.01 250)" }}
      >
        <div className="p-4">
          {loading ? (
            <div className="text-text-secondary/50 animate-pulse">
              Loading logs...
            </div>
          ) : (
            <>
              {logs.map((line, i) => {
                const isError =
                  line.includes("Error") ||
                  line.includes("error") ||
                  line.includes("Traceback") ||
                  line.includes("TIMEOUT") ||
                  line.includes("killed") ||
                  line.includes("FAILED");
                const isWarning =
                  line.includes("WARNING") || line.includes("warning");

                return (
                  <div
                    key={i}
                    className="py-0.5 hover:bg-white/[0.02] rounded px-2 -mx-1"
                  >
                    <span className="text-text-secondary/30 select-none mr-4 inline-block w-5 text-right tabular-nums">
                      {i + 1}
                    </span>
                    <span
                      className={cn(
                        isError
                          ? "text-error/80"
                          : isWarning
                            ? "text-warning/80"
                            : "text-text-primary/70"
                      )}
                    >
                      {line}
                    </span>
                  </div>
                );
              })}
              {run.status === "running" && (
                <div className="py-0.5 px-2 -mx-1">
                  <span className="text-text-secondary/30 select-none mr-4 inline-block w-5 text-right tabular-nums">
                    {logs.length + 1}
                  </span>
                  <span className="text-info animate-pulse">
                    Waiting for output...
                  </span>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
