import {
  jobs as mockJobs,
  runs as mockRuns,
  runLogs as mockRunLogs,
  type Job as MockJob,
  type Run as MockRun,
} from "./mock-data";

const API_BASE = "http://127.0.0.1:8377";

/* ── API response types (matching OpenAPI spec) ──────────────────────────── */

export interface ApiJob {
  id: string;
  name: string;
  schedule: string;
  execution: { type: string; value: string };
  enabled: boolean;
  timezone: string | null;
  working_dir: string | null;
  env_vars: Record<string, string> | null;
  timeout_secs: number;
  log_environment: boolean;
  allow_concurrent: boolean;
  schedule_mode: string;
  created_at: string;
  updated_at: string;
  last_run_at: string | null;
  last_exit_code: number | null;
  next_run_at: string | null;
  pre_hook: string | null;
  post_hook: string | null;
  pre_hook_script_type: string | null;
  post_hook_script_type: string | null;
}

export interface ApiRun {
  run_id: string;
  job_id: string;
  job_name?: string;
  started_at: string;
  finished_at: string | null;
  status: "Running" | "Completed" | "CompletedWithWarnings" | "Failed" | "Killed";
  exit_code: number | null;
  log_size_bytes: number;
  error: string | null;
  total_cost_usd: number | null;
  duration_ms: number | null;
  num_turns: number | null;
  model: string | null;
}

export interface ApiHealth {
  status: string;
  uptime_seconds: number;
  active_jobs: number;
  total_jobs: number;
  version: string;
  data_dir: string;
}

export interface RunListResponse {
  runs: ApiRun[];
  total: number;
  limit: number;
  offset: number;
}

/* ── Normalizers (API shape -> internal shape) ───────────────────────────── */

export function normalizeJob(api: ApiJob): MockJob {
  const hasRunningStatus = false; // We'll check runs separately
  let status: MockJob["status"];
  if (!api.enabled) {
    status = "disabled";
  } else if (api.last_exit_code === null && api.last_run_at === null) {
    status = "ok";
  } else if (api.last_exit_code === 0) {
    status = "ok";
  } else if (api.last_exit_code !== null && api.last_exit_code !== 0) {
    status = "failed";
  } else {
    status = "ok";
  }

  const nextRunLabel = api.next_run_at ? formatRelativeFuture(api.next_run_at) : null;

  return {
    id: api.id,
    name: api.name,
    schedule: api.schedule,
    status,
    enabled: api.enabled,
    execType: (api.execution.type as "ShellCommand" | "ScriptFile") || "ShellCommand",
    command: api.execution.value,
    workingDir: api.working_dir || "",
    shell: "/bin/bash",
    timeout: api.timeout_secs > 0 ? formatTimeout(api.timeout_secs) : "None",
    maxRetries: 0,
    allowConcurrent: api.allow_concurrent,
    scheduleMode: api.schedule_mode === "WaitForCompletion" ? "interval" : "cron",
    preHook: api.pre_hook || "",
    postHook: api.post_hook || "",
    preHookScriptType: api.pre_hook_script_type || null,
    postHookScriptType: api.post_hook_script_type || null,
    envVars: api.env_vars || {},
    logEnvironment: api.log_environment ?? false,
    created: api.created_at ? new Date(api.created_at).toLocaleString() : "",
    lastRun: api.last_run_at ? new Date(api.last_run_at).toLocaleString() : "Never",
    nextRun: nextRunLabel,
  };
}

export function normalizeRun(api: ApiRun, jobName?: string): MockRun {
  const statusMap: Record<string, MockRun["status"]> = {
    Running: "running",
    Completed: "success",
    CompletedWithWarnings: "success",
    Failed: "failed",
    Killed: "killed",
  };

  const durationStr = api.duration_ms
    ? formatDuration(api.duration_ms)
    : api.status === "Running"
      ? "running"
      : "--";

  const costStr = api.total_cost_usd != null
    ? `$${api.total_cost_usd.toFixed(2)}`
    : "--";

  return {
    id: api.run_id,
    jobId: api.job_id,
    jobName: api.job_name || jobName || api.job_id,
    status: statusMap[api.status] || "failed",
    started: api.started_at ? new Date(api.started_at).toLocaleString() : "",
    finished: api.finished_at ? new Date(api.finished_at).toLocaleString() : "--",
    exitCode: api.exit_code,
    cost: costStr,
    duration: durationStr,
  };
}

/* ── Formatters ──────────────────────────────────────────────────────────── */

function formatTimeout(secs: number): string {
  if (secs >= 3600) return `${Math.round(secs / 3600)}h`;
  if (secs >= 60) return `${Math.round(secs / 60)}m`;
  return `${secs}s`;
}

function formatDuration(ms: number): string {
  const secs = Math.round(ms / 1000);
  if (secs < 60) return `${secs}s`;
  const mins = Math.floor(secs / 60);
  const remSecs = secs % 60;
  if (mins < 60) return `${mins}m ${remSecs}s`;
  const hrs = Math.floor(mins / 60);
  const remMins = mins % 60;
  return `${hrs}h ${remMins}m`;
}

function formatRelativeFuture(isoDate: string): string {
  const target = new Date(isoDate);
  const now = new Date();
  const diffMs = target.getTime() - now.getTime();
  if (diffMs <= 0) return "now";
  const mins = Math.round(diffMs / 60000);
  if (mins < 60) return `in ${mins}m`;
  const hrs = Math.floor(mins / 60);
  const remMins = mins % 60;
  if (hrs < 24) return `in ${hrs}h ${remMins}m`;
  const days = Math.round(hrs / 24);
  return `in ${days}d`;
}

/* ── API fetch functions ─────────────────────────────────────────────────── */

export async function fetchJobs(): Promise<MockJob[]> {
  try {
    const res = await fetch(`${API_BASE}/api/jobs`, {
      cache: "no-store",
      signal: AbortSignal.timeout(3000),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data: ApiJob[] = await res.json();
    return data.map(normalizeJob);
  } catch {
    console.warn("[api] fetchJobs failed, using mock data");
    return mockJobs;
  }
}

export async function fetchJobRuns(
  jobId: string,
  limit = 20
): Promise<MockRun[]> {
  try {
    const res = await fetch(
      `${API_BASE}/api/jobs/${jobId}/runs?limit=${limit}`,
      { cache: "no-store", signal: AbortSignal.timeout(3000) }
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data: RunListResponse = await res.json();
    return data.runs.map((r) => normalizeRun(r));
  } catch {
    console.warn(`[api] fetchJobRuns(${jobId}) failed, using mock data`);
    return mockRuns.filter((r) => r.jobId === jobId);
  }
}

export async function fetchRecentRuns(limit = 20): Promise<MockRun[]> {
  try {
    const res = await fetch(
      `${API_BASE}/api/runs/recent?limit=${limit}`,
      { cache: "no-store", signal: AbortSignal.timeout(3000) }
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data: { runs: ApiRun[]; limit: number } = await res.json();
    return data.runs.map((r) => normalizeRun(r));
  } catch {
    console.warn("[api] fetchRecentRuns failed, using mock data");
    return mockRuns;
  }
}

export async function fetchHealth(): Promise<ApiHealth | null> {
  try {
    const res = await fetch(`${API_BASE}/health`, {
      cache: "no-store",
      signal: AbortSignal.timeout(3000),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch {
    console.warn("[api] fetchHealth failed");
    return null;
  }
}

export async function fetchRunLog(runId: string): Promise<string[]> {
  try {
    const res = await fetch(`${API_BASE}/api/runs/${runId}/log`, {
      cache: "no-store",
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const text = await res.text();
    return text.split("\n").filter((line) => line.length > 0);
  } catch {
    console.warn(`[api] fetchRunLog(${runId}) failed, using mock data`);
    return mockRunLogs[runId] || ["(No log data available)"];
  }
}
